package com.example

import com.example.ExamQuestionHelper.QSpec

/**
 * Curated Geography Live Exam Hall Bank — Domain 7:
 * ආර්ථික භූගෝල විද්‍යාව, කෘෂිකර්මය හා කර්මාන්ත (Economic Geography, Agriculture & Industry)
 */
internal object GeographyLiveExamEconomicBank {
  private fun q(t: String, s: String, c: String, d1: String, d2: String, d3: String, e: String) =
    QSpec(t, s, c, listOf(d1, d2, d3), e)

  fun economicGeographyQuestions(): List<QSpec> {
    val t = "ආර්ථික භූගෝල විද්‍යාව, කෘෂිකර්මය හා කර්මාන්ත"
    return listOf(
      q(t, "ආර්ථික ක්‍රියාකාරකම් වර්ගීකරණයේදී 'ප්‍රාථමික අංශයට' (Primary Economic Activities) අයත් වන්නේ කුමන කටයුතුද?",
        "කෘෂිකර්මාන්තය, ධීවර කර්මාන්තය, වන කර්මාන්තය සහ පතල් කැණීම වැනි ස්වභාවධර්මයෙන් සෘජුවම සම්පත් ලබා ගැනීමේ කටයුතු", "භාණ්ඩ නිෂ්පාදන කර්මාන්ත", "බැංකු හා රක්ෂණ සේවා", "මෘදුකාංග සංවර්ධනය",
        "ආර්ථික අංශ 4: ප්‍රාථමික (අමුද්‍රව්‍ය ලබාගැනීම), ද්විතීයික (නිෂ්පාදනය), තෘතීයික (සේවා) සහ චතුර්ථක (තොරතුරු හා පර්යේෂණ) වේ."),
      q(t, "'ද්විතීයික අංශයේ' (Secondary Sector) ප්‍රධාන කාර්යභාරය කුමක්ද?",
        "ප්‍රාථමික අංශයෙන් ලබාගත් අමුද්‍රව්‍ය කර්මාන්තශාලාවලදී වඩා වටිනා නිමි භාණ්ඩ බවට පරිවර්තනය කිරීම (නිෂ්පාදන හා ඉදිකිරීම්)", "පස හෑරීම", "බැංකු සේවා සැපයීම", "පාසල් ඉගැන්වීම",
        "යපස් වානේ බවටද, කපු නූල් හා ඇඳුම් බවටද, කිරි යෝගට් හා චීස් බවටද පත් කිරීම ද්විතීයික ක්‍රියාකාරකම් වේ."),
      q(t, "'තෘතීයික අංශය' (Tertiary Sector) සහ 'චතුර්ථක අංශය' (Quaternary Sector) අතර වෙනස කුමක්ද?",
        "තෘතීයික අංශය ප්‍රවාහනය, වෙළඳාම, සෞඛ්‍ය, අධ්‍යාපනය හා සංචාරක සේවා සපයන අතර චතුර්ථක අංශය තොරතුරු තාක්ෂණය, විද්‍යාත්මක පර්යේෂණ හා මූල්‍ය උපදේශන වැනි දැනුම-මූලික සේවා සපයයි", "දෙකම ගොවිතැන වේ", "චතුර්ථක අංශය යනු පතල් කැණීමයි", "වෙනසක් නැත",
        "ඉහළ තීරණ ගන්නා විධායක නිලධාරීන්, විද්‍යාඥයන් හා ප්‍රතිපත්ති සම්පාදකයන් ඇතැම් විට පංචම (Quinary) අංශයට වර්ග කෙරේ."),
      q(t, "'යැපුම් කෘෂිකර්මය' (Subsistence Agriculture) සහ 'වාණිජ කෘෂිකර්මය' (Commercial Agriculture) අතර ප්‍රධාන වෙනස කුමක්ද?",
        "යැපුම් කෘෂිකර්මයේදී ගොවි පවුලේ පරිභෝජනය සඳහා කුඩා බිම් කැබලිවල වගා කරන අතර වාණිජ කෘෂිකර්මයේදී වෙළඳපොළේ විකුණා ලාභ ලැබීමට මහා පරිමාණයෙන් වගා කෙරේ", "වාණිජ කෘෂිකර්මයේදී ආහාර වගා නොකරයි", "යැපුම් කෘෂිකර්මයට යන්ත්‍රෝපකරණ 100% ක් භාවිත කරයි", "කිසිදු වෙනසක් නැත",
        "හේන් ගොවිතැන සාම්ප්‍රදායික යැපුම් කෘෂිකර්මයටත්, වතු තේ වගාව හා ඇමරිකානු තිරිඟු ගොවිපළ වාණිජ කෘෂිකර්මයටත් නිදසුන් වේ."),
      q(t, "නිවර්තන වනාන්තරවල සාම්ප්‍රදායිකව සිදු කරන 'වගා මාරු / හේන් කෘෂිකර්මය' (Shifting Cultivation / Slash-and-Burn) යනු කුමක්ද?",
        "වනාන්තර බිම් කොටසක් හෙළි කර පුළුස්සා එහි අළු පොහොර මත කන්න කිහිපයක් වගා කර පස නිසරු වූ පසු එම ඉඩම අතහැර වෙනත් බිමකට යාම", "එකම කුඹුරක වසර 100 ක් වගා කිරීම", "රසායනික පොහොර ටොන් ගණන් දැමීම", "ට්‍රැක්ටර් යොදා තිරිඟු වැවීම",
        "ශ්‍රී ලංකාවේ 'හේන්' (Chena) ලෙසද, ඉන්දුනීසියාවේ 'ලඩාං' (Ladang) ලෙසද, බ්‍රසීලයේ 'රොකා' (Roca) ලෙසද හැඳින්වේ."),
      q(t, "'තීව්‍ර යැපුම් කෘෂිකර්මය' (Intensive Subsistence Agriculture) දකුණු හා අග්නිදිග ආසියාවේ බහුල වීමට හේතුව කුමක්ද?",
        "ඉහළ ජන ඝනත්වය නිසා කුඩා ගොවි බිම් ප්‍රමාණයකින් උපරිම අස්වැන්නක් ලබා ගැනීමට විශාල මිනිස් ශ්‍රමයක් යොදා වගා කිරීම (විශේෂයෙන් තෙත් වී වගාව)", "ඉඩම් අසීමිත ලෙස වැඩි වීම", "ජනගහනය ඉතා අඩු වීම", "කාන්තාර දේශගුණය",
        "නිසි ජල සම්පාදනයෙන් වසරකට කන්න දෙකක් හෝ තුනක් (Double/Triple Cropping) වී අස්වැන්න නෙළා ගැනේ."),
      q(t, "'වතු කෘෂිකර්මයේ' (Plantation Agriculture) ප්‍රධාන ලක්ෂණ මොනවාද?",
        "යටත් විජිත සමයේ ආරම්භ වූ මහා පරිමාණ ඉඩම්වල අපනයන වෙළඳපොළ ඉලක්ක කර තේ, රබර්, පොල්, කෝපි, කොකෝවා හෝ උක් වැනි ඒක-බෝග වගා කිරීම", "පවුලේ ආහාරයට පමණක් වගා කිරීම", "කුඩා පෝච්චිවල වගා කිරීම", "ශීත ධ්‍රැව කලාපයේ පිහිටීම",
        "වතු වගාවන්හි නිෂ්පාදන සැකසීමේ කර්මාන්තශාලාද බොහෝ විට වත්ත ඇතුළතම පිහිටා ඇත."),
      q(t, "'විස්තීරණ වාණිජ ධාන්‍ය වගාව' (Extensive Commercial Grain Farming) සිදු කරන ප්‍රධාන භූගෝලීය කලාප මොනවාද?",
        "උතුරු ඇමරිකාවේ ප්‍රේරි, යුක්රේන/රුසියානු ස්ටෙප්ස්, ආර්ජන්ටිනාවේ පැම්පාස් සහ ඔස්ට්‍රේලියානු ඩවුන්ස් සෞම්‍ය තණබිම්", "සමක වැසි වනාන්තර", "හිමාලය මුදුන්", "කොරල් දූපත්",
        "විශාල පැතලි ගොවිපළවල ට්‍රැක්ටර්, කම්බයින් හාවෙස්ටර් හා ගුවන් යානා මගින් ඉහළ යාන්ත්‍රිකරණයක් යටතේ තිරිඟු වගා කෙරේ."),
      q(t, "'මිශ්‍ර ගොවිතැන' (Mixed Farming - බටහිර යුරෝපය, නැගෙනහිර උතුරු ඇමරිකාව, නවසීලන්තය) ගොවීන්ට ආර්ථික හා පාරිසරික ආරක්ෂාවක් සපයන්නේ කෙසේද?",
        "එකම ගොවිපළක බෝග වගාව සහ සත්ත්ව පාලනය (ගවයන්, ඌරන්, කුකුළන්) එකට කිරීමෙන් ආදායම් මූලාශ්‍ර විවිධාංගීකරණය වීමත්, සත්ත්ව ගොම පොහොර ලෙස හා බෝග අවශේෂ සත්ත්ව ආහාර ලෙස භාවිත වීමත්", "වසර පුරා එක් භෝගයක් පමණක් වැවීම", "විකිණීම තහනම් කිරීම", "රසායනික පොහොර පමණක් භාවිතය",
        "බෝග අස්වැන්න අසාර්ථක වූවත් කිරි හා මස් අලෙවියෙන් ගොවියාට ස්ථාවර ආදායමක් ලැබේ."),
      q(t, "'කිරි ගොවිපළ කර්මාන්තය' (Dairy Farming) ප්‍රධාන නාගරික මධ්‍යස්ථාන ආසන්නයේ හෝ සෞම්‍ය තෙත් තෘණ භූමිවල (ඩෙන්මාර්කය, නවසීලන්තය, නෙදර්ලන්තය) සංකේන්ද්‍රණය වී ඇත්තේ ඇයි?",
        "නැවුම් කිරි ඉක්මනින් නරක් වන බැවින් වෙළඳපොළට ආසන්න වීමත්, සෞම්‍ය තෙත් දේශගුණය වසර පුරා සාරවත් තණකොළ වගාවටත් සුදුසු වීමත්", "කාන්තාර වැලි බහුල වීම", "අධික උණුසුම නිසා කිරි රත් වීම", "වනාන්තර කැපීමට",
        "ශීතකරණ නැව් හා කිරිපිටි තාක්ෂණය නිසා නවසීලන්තයට ලෝකය පුරාම කිරි නිෂ්පාදන අපනයනය කිරීමට හැකි වී ඇත."),
      q(t, "'මධ්‍යධරණී කෘෂිකර්මය' (Mediterranean Agriculture) විශේෂිත වී ඇත්තේ කුමන ඉහළ වටිනාකමකින් යුත් බෝග සඳහාද?",
        "මිදි (වයින් නිෂ්පාදනය), ඔලිව්, දොඩම්/ලෙමන් වැනි පැඟිරි පලතුරු, අත්තික්කා සහ මල් වගාව", "තෙත් වී හා ජූට්", "රබර් හා තෙල් පාම්", "උක් හා කෙසෙල් පමණි",
        "ශීත ඍතු වැසි හා උණුසුම් වියළි ගිම්හානය මෙම ගැඹුරු මුල් ඇති පලතුරු බෝගවල සීනි සාන්ද්‍රණය වැඩි කිරීමට උපකාරී වේ."),
      q(t, "'වෙළඳපොළ ගෙවතු වගාව සහ මල් වගාව' (Market Gardening & Horticulture / Truck Farming) නගර ආසන්නයේ පිහිටුවීමට හේතුව කුමක්ද?",
        "නැවුම් එළවළු, පලතුරු හා කැපූ මල් ඉක්මනින් මැලවෙන බැවින් නාගරික පාරිභෝගිකයන්ට දිනපතා අලුතින් සැපයීමට ප්‍රවාහන දුර අවම විය යුතු නිසා", "නගරයේ හිම වැඩි නිසා", "ගොවීන් නැති නිසා", "වැසි නැති නිසා",
        "ශ්‍රී ලංකාවේ නුවරඑළිය, වැලිමඩ හා කල්පිටිය කොළඹ නාගරික වෙළඳපොළට එළවළු සපයන ප්‍රධාන කලාප වේ."),
      q(t, "ජොහැන් වොන් තූනන්ගේ (Johann von Thünen - 1826) 'කෘෂිකාර්මික ඉඩම් පරිභෝජන ආකෘතිය' අනුව මධ්‍යම නගරය වටා ඇති වළලු තීරණය වන්නේ කුමන සාධක දෙක මතද?",
        "ඉඩම් කුලිය (Land Rent) සහ වෙළඳපොළට නිෂ්පාදන ගෙන යාමේ ප්‍රවාහන පිරිවැය (Transportation Cost)", "සුළං වේගය හා උෂ්ණත්වය", "භූ කම්පන හා ගිනිකඳු", "ජාතික භාෂාව",
        "එබැවින් ඉක්මනින් නරක් වන හා බරින් වැඩි කිරි හා එළවළු නගරයට ආසන්නම පළමු වළල්ලේද, දර/දැව දෙවන වළල්ලේද, ධාන්‍ය හා සත්ත්ව පාලනය බාහිර වළලුවලද පිහිටයි."),
      q(t, "1960 ගණන්වල ආසියාවේ හා ලතින් ඇමරිකාවේ ක්‍රියාත්මක කළ 'හරිත විප්ලවය' (Green Revolution) මගින් සාගත අවදානම අඩු කිරීමට යොදා ගත් ප්‍රධාන තාක්ෂණයන් මොනවාද?",
        "ඉහළ අස්වනු ලබා දෙන වැඩිදියුණු කළ බීජ (HYV - තිරිඟු හා සහල්), රසායනික පොහොර, පළිබෝධනාශක හා පුළුල් වාරි ජල සම්පාදනය", "වනාන්තර වගාව පමණි", "සතුන්ගෙන් හෑම පමණි", "ගුවන් යානා මගින් ආහාර හෙළීම",
        "නෝමන් බෝර්ලොග් මෙහි පුරෝගාමියා වූ අතර ඉන්දියාවේ හා පිලිපීනයේ ධාන්‍ය අස්වැන්න දෙගුණ-තෙගුණ වුවද අධික රසායනික භාවිතය නිසා පාංශු/ජල දූෂණ ගැටලුද මතු විය."),
      q(t, "'නිරවද්‍ය කෘෂිකර්මය' (Precision Agriculture / Smart Farming) නූතන ගොවිතැනේදී වැදගත් වන්නේ කෙසේද?",
        "GPS, පාංශු සංවේදක, ඩ්‍රෝන යානා හා චන්ද්‍රිකා දත්ත භාවිත කරමින් ජලය, පොහොර හා පළිබෝධනාශක අවශ්‍යම තැනට අවශ්‍ය ප්‍රමාණයට පමණක් යොදා නාස්තිය හා දූෂණය අවම කිරීම", "සමස්ත ගොවිපළටම විෂ ඉසීම", "යන්ත්‍ර සම්පූර්ණයෙන් ඉවත් කිරීම", "අනුමානයෙන් වගා කිරීම",
        "නිරවද්‍ය කෘෂිකර්මය මගින් නිෂ්පාදන වියදම අඩු වන අතර අස්වැන්න හා පාරිසරික තිරසාරභාවය ඉහළ යයි."),
      q(t, "'කාබනික ගොවිතැන' (Organic Farming) සාම්ප්‍රදායික රසායනික ගොවිතැනින් වෙනස් වන්නේ කුමන පිළිවෙත් නිසාද?",
        "කෘත්‍රිම රසායනික පොහොර, පළිබෝධනාශක හා ජාන විකරණය කළ බීජ (GMO) භාවිත නොකර කොම්පෝස්ට්, කොළ පොහොර, බෝග මාරුව හා ජීව විද්‍යාත්මක පළිබෝධ පාලනය යොදා ගැනීම", "වැඩිපුර රසායනික ඉසීම", "වීදුරු වලින් පස වැසීම", "සූර්යාලෝකය නතර කිරීම",
        "කාබනික කෘෂි නිෂ්පාදන සඳහා ජාත්‍යන්තර වෙළඳපොළේ ඉහළ මිලක් පැවතියද ආරම්භක කාලයේ අස්වැන්න සාපේක්ෂව අඩු විය හැකිය."),
      q(t, "ඇල්ෆ්‍රඩ් වෙබර්ගේ (Alfred Weber - 1909) 'කාර්මික පිහිටුම් න්‍යාය' (Industrial Location Theory) අනුව කර්මාන්තශාලාවක් පිහිටුවීමේදී අවම කිරීමට උත්සාහ කරන ප්‍රධාන පිරිවැය කුමක්ද?",
        "අමුද්‍රව්‍ය ගෙන ඒමේ හා නිමි භාණ්ඩ වෙළඳපොළට යැවීමේ මුළු ප්‍රවාහන පිරිවැය (සහ ශ්‍රම හා ඒකරාශී වීමේ පිරිවැය)", "කම්කරු නිවාඩු දින", "වැසි ජල ප්‍රමාණය", "ගොඩනැගිලි වර්ණය",
        "බර හා විශාල අමුද්‍රව්‍ය සැහැල්ලු නිමි භාණ්ඩ බවට පත් කරන කර්මාන්ත (බර-අඩු වන / Weight-Losing: සීනි, වානේ, තඹ උණු කිරීම) අමුද්‍රව්‍ය ප්‍රභවය අසලම පිහිටුවයි."),
      q(t, "'බර-වැඩි වන කර්මාන්ත' (Weight-Gaining / Bulk-Gaining Industries - උදා: බීම බෝතල් කිරීම, බේකරි, මෝටර් රථ එකලස් කිරීම) බොහෝ විට පිහිටුවන්නේ කොතැනද?",
        "පාරිභෝගික වෙළඳපොළට ඉතා ආසන්නව (Market-Oriented)", "පතල් පතුලේ", "දුරස්ථ කඳු මුදුන්වල", "කාන්තාර මධ්‍යයේ",
        "උදාහරණයක් ලෙස සිසිල් බීම සෑදීමේදී සාන්ද්‍ර සිරප්වලට ජලය විශාල ප්‍රමාණයක් එකතු කර බර වැඩි කරන බැවින් බෝතල් කිරීමේ කම්හල් නගර අසල පිහිටුවයි."),
      q(t, "'නිදහස් පිහිටුම් කර්මාන්ත' (Footloose Industries - උදා: ඉලෙක්ට්‍රොනික උපාංග, මෘදුකාංග, ඔරලෝසු, ඖෂධ) සඳහා නිශ්චිත අමුද්‍රව්‍ය ප්‍රභවයක් අසලම පිහිටීම අනිවාර්ය නොවන්නේ ඇයි?",
        "අමුද්‍රව්‍ය හා නිමි භාණ්ඩ බරින් ඉතා අඩු, කුඩා සහ ඉහළ මූල්‍ය වටිනාකමකින් යුක්ත වන බැවින් ප්‍රවාහන පිරිවැය නොසැලකිය හැකි තරම් කුඩා වීම", "ඒවා ගුවනේ පාවෙන බැවින්", "ඒවාට කිසිදු සේවකයෙකු අවශ්‍ය නොවන බැවින්", "ඒවා විකුණන්නේ නැති බැවින්",
        "මෙම කර්මාන්ත පුහුණු ශ්‍රමය, විශ්වවිද්‍යාල, අධිවේගී අන්තර්ජාලය, ගුවන්තොටුපළ හා ප්‍රසන්න ජීවන පරිසරය අසල පිහිටුවයි."),
      q(t, "'කාර්මික ඒකරාශී වීම' (Industrial Agglomeration) නිසා එකම ක්ෂේත්‍රයේ කර්මාන්ත එකම කලාපයක පොකුරු ගැසීමෙන් ලැබෙන වාසිය කුමක්ද?",
        "පොදු ප්‍රවාහන/විදුලි පහසුකම්, පුහුණු ශ්‍රම වෙළඳපොළ, විශේෂිත සැපයුම්කරුවන් හා තාක්ෂණික දැනුම බෙදා ගැනීමෙන් නිෂ්පාදන පිරිවැය අඩු වීම", "ප්‍රවාහන වියදම 10 ගුණයකින් වැඩිවීම", "ශ්‍රමිකයන් නැති වීම", "වෙළඳපොළ අහිමි වීම",
        "කැලිෆෝනියාවේ සිලිකන් නිම්නය (IT) සහ ඉන්දියාවේ බැංගලෝර් තාක්ෂණික ඒකරාශී වීමට විශිෂ්ට උදාහරණ වේ."),
      q(t, "'යකඩ හා වානේ කර්මාන්තය' (Iron & Steel Industry) සියලුම කර්මාන්තවල 'මූලික / කොඳු නාරටි කර්මාන්තය' ලෙස හඳුන්වන්නේ ඇයි?",
        "මෝටර් රථ, නැව්, දුම්රිය, පාලම්, ගොඩනැගිලි, කෘෂි යන්ත්‍ර හා කර්මාන්තශාලා යන්ත්‍රෝපකරණ නිපදවීමට අත්‍යවශ්‍ය මූලික ලෝහය වානේ බැවින්", "එය ඉතා සැහැල්ලු බැවින්", "එය කෑමට ගන්නා බැවින්", "එය රෙදි වලින් හදන බැවින්",
        "වානේ ටොන් එකක් නිපදවීමට යපස්, කෝකිං ගල් අඟුරු සහ හුණුගල් ප්‍රධාන වශයෙන් අවශ්‍ය වේ."),
      q(t, "පැරණි ගල් අඟුරු පතල් ආශ්‍රිත කාර්මික කලාපවල (උදා: ජර්මනියේ රුර් නිම්නය, බ්‍රිතාන්‍යයේ මිඩ්ලන්ඩ්ස්) සිට නවීන වානේ කම්හල් වෙරළබඩ වරායන් වෙත (උදා: ජපානයේ ඔසාකා-කෝබේ, දකුණු කොරියාවේ පොහාං) මාරු වූයේ ඇයි?",
        "දේශීය ගල් අඟුරු හා යපස් අවසන් වීමත්, විදේශයන්ගෙන් විශාල නැව් මගින් ආනයනය කරන ලාභදායී යපස් හා ගල් අඟුරු සෘජුවම වරාය අසලදී බා ගැනීමේ පහසුවත්", "කඳු මුදුනට නැව් යන නිසා", "ගල් අඟුරු වතුරේ දියවන නිසා", "මුහුදු වැලිවලින් වානේ හදන නිසා",
        "ජපානයේ ස්වාභාවික යපස් හෝ ගල් අඟුරු ඉතා අඩු වුවද වෙරළාශ්‍රිත වානේ කර්මාන්තයෙන් ලොව ප්‍රමුඛයෙකු බවට පත් විය."),
      q(t, "'නිෂ්පාදන ක්‍රියාවලිය බාහිරින් ලබා ගැනීම' (Outsourcing / Offshoring) හරහා බහුජාතික සමාගම් සිය කර්මාන්තශාලා සංවර්ධනය වෙමින් පවතින ආසියානු රටවල පිහිටුවන්නේ ඇයි?",
        "සාපේක්ෂව අඩු ශ්‍රම පිරිවැය, විශාල කම්කරු සැපයුම, බදු සහන හා වේගයෙන් වර්ධනය වන දේශීය වෙළඳපොළවල් ප්‍රයෝජනයට ගැනීමට", "ප්‍රවාහන වියදම් වැඩි කිරීමට", "භාණ්ඩ මිල 10 ගුණයකින් ඉහළ දැමීමට", "සේවකයන් අඩු කිරීමට",
        "ඇඟලුම්, සපත්තු හා ඉලෙක්ට්‍රොනික එකලස් කිරීමේ කර්මාන්ත චීනය, වියට්නාමය, බංග්ලාදේශය, ඉන්දියාව හා ශ්‍රී ලංකාව වෙත ව්‍යාප්ත වූයේ මේ අනුවය."),
      q(t, "ශ්‍රී ලංකාවේ 'අපනයන සැකසුම් කලාප' (Export Processing Zones - EPZs, උදා: කටුනායක, බියගම, කොග්ගල) ආර්ථිකයට දායක වන්නේ කෙසේද?",
        "විදේශ සෘජු ආයෝජන (FDI) ආකර්ෂණය කිරීම, විශාල වශයෙන් තරුණ රැකියා (විශේෂයෙන් කාන්තා ශ්‍රමය) උත්පාදනය කිරීම සහ ඇඟලුම්, රබර් නිෂ්පාදන වැනි කාර්මික අපනයන ආදායම වැඩි කිරීම", "ආනයන පමණක් වැඩි කිරීම", "වරායන් වසා දැමීම", "දේශීය කෘෂිකර්මය තහනම් කිරීම",
        "1978 දී පිහිටුවන ලද කටුනායක අපනයන සැකසුම් කලාපය බණ්ඩාරනායක ජාත්‍යන්තර ගුවන්තොටුපළට හා කොළඹ වරායට ආසන්නව පිහිටීම විශාල වාසියකි."),
      q(t, "ශ්‍රී ලංකාවේ ප්‍රධානම කාර්මික අපනයන අංශය වන 'ඇඟලුම් කර්මාන්තය' (Apparel Industry) ජාත්‍යන්තර වෙළඳපොළේ තරඟකාරීව රැඳී සිටීම සඳහා අනුගමනය කර ඇති උපායමාර්ගය කුමක්ද?",
        "සාමාන්‍ය ලාභ ඇඳුම් වෙනුවට සදාචාරාත්මක නිෂ්පාදන ('Garments Without Guilt'), හරිත කර්මාන්තශාලා සහ ඉහළ අගය එකතු කළ ක්‍රීඩා හා විශේෂිත ඇඟලුම් නිපදවීම", "ළමා ශ්‍රමය භාවිත කිරීම", "පරිසර නීති සම්පූර්ණයෙන් කඩ කිරීම", "කපු වගාව පමණක් කිරීම",
        "ශ්‍රී ලංකාවේ හරිත ඇඟලුම් කර්මාන්තශාලා ලොව ප්‍රමුඛ ගෝලීය සන්නාම සඳහා සැපයුම් සිදු කරයි."),
      q(t, "'තේ කර්මාන්තය' ශ්‍රී ලංකාවේ ආර්ථික භූගෝල විද්‍යාවේ සුවිශේෂී ස්ථානයක් ගන්නේ කෙසේද? ('Ceylon Tea')",
        "විවිධ උන්නතාංශ කලාප තුනකින් (උඩරට, මැදරට, පහතරට) විවිධ රසයන්ගෙන් යුත් තේ නිපදවීමත්, සිංගල් ඔරිජින් හා කළු/හරිත/රිදී තේ අගය එකතු කළ අපනයන මගින් විදේශ විනිමය ඉපැයීමත්", "මුහුදු වෙරළේ වැලි මත පමණක් වැවීමත්", "වසරකට එක් වරක් පමණක් දළු කැඩීමත්", "සම්පූර්ණයෙන් දේශීයව පරිභෝජනය කිරීමත්",
        "පහතරට තේ (රුහුණ, සබරගමුව) මැදපෙරදිග හා රුසියානු වෙළඳපොළවල ඉතා ජනප්‍රිය වන අතර නුවරඑළිය හා දිඹුල උඩරට තේ සුවඳ හා සැහැල්ලු රසයට ප්‍රසිද්ධය."),
      q(t, "ප්‍රවාහන භූගෝල විද්‍යාවේ 'සාගර / නාවික ප්‍රවාහනය' (Maritime Transport) ජාත්‍යන්තර භාණ්ඩ ප්‍රවාහනයෙන් ~80%+ පරිමාවක් ආවරණය කරන්නේ ඇයි?",
        "බහාලුම් නැව් (Container Ships) හා තොග නැව් මගින් අතිවිශාල බර හා පරිමා භාණ්ඩ ටොන් ගණනක් ටොන්-කිලෝමීටරයකට අවම පිරිවැයකින් දිගු දුර ප්‍රවාහනය කළ හැකි බැවින්", "නැව් ගුවන් යානාවලට වඩා වේගවත් බැවින්", "සෑම නිවසකටම නැව් යන බැවින්", "ඉන්ධන අවශ්‍ය නොවන බැවින්",
        "ඉක්මනින් නරක් වන මල්, ඖෂධ හා හදිසි ඉලෙක්ට්‍රොනික භාණ්ඩ සඳහා පිරිවැය වැඩි වුවද වේගවත් ගුවන් ප්‍රවාහනය යොදා ගැනේ."),
      q(t, "ප්‍රවාහන ක්‍රම අතර 'බහු-මාදිලි බහාලුම් ප්‍රවාහනය' (Containerization / Intermodal Transport) ගෝලීය වෙළඳාමේ විප්ලවයක් ඇති කළේ කෙසේද?",
        "සම්මත ප්‍රමාණයේ වානේ කන්ටේනර් (TEU) තුළ භාණ්ඩ ඇසුරුම් කර ඒවා විවෘත නොකරම දොඹකර මගින් නැවෙන් දුම්රියට හා ට්‍රක් රථයට ඉක්මනින් මාරු කිරීමෙන් පැටවුම් කාලය, හානි හා පිරිවැය විශාල ලෙස අඩු වීම", "සෑම වරායකදීම පෙට්ටි කඩා අතින් ඇදීම", "නැව් ප්‍රමාණය කුඩා කිරීම", "දුම්රිය මාර්ග ගැලවීම",
        "1950 ගණන්වල ඇරඹි කන්ටේනර්කරණය නූතන ගෝලීය සැපයුම් දාමයන් (Global Supply Chains) කළ හැකි බවට පත් කළේය."),
      q(t, "ලෝක නාවික ගමනාගමනයේ කාලය හා දුර සැතපුම් දහස් ගණනක් ඉතිරි කරන ප්‍රධාන කෘත්‍රිම නාවික ඇළ මාර්ග දෙක මොනවාද?",
        "සූවස් ඇළ (Suez Canal - මධ්‍යධරණී හා රතු මුහුද යා කරයි) සහ පැනමා ඇළ (Panama Canal - අත්ලාන්තික් හා පැසිෆික් සාගර යා කරයි)", "නයිල් ඇළ සහ ඇමසන් ඇළ", "යෝධ ඇළ සහ ජය ගඟ", "කීල් ඇළ සහ වික්ටෝරියා ඇළ",
        "සූවස් ඇළ නොමැති නම් යුරෝපයේ සිට ආසියාවට යන නැව්වලට අප්‍රිකාවේ සුබ පැත්තේ තුඩුව වටා දින 10–14 ක් වැඩිපුර ගමන් කිරීමට සිදුවේ."),
      q(t, "'ජාත්‍යන්තර වෙළඳාම' (International Trade) රටවල් අතර අත්‍යවශ්‍ය වන්නේ කුමන ආර්ථික මූලධර්මය මතද?",
        "සියලු රටවල ස්වාභාවික සම්පත්, දේශගුණය, තාක්ෂණය හා ශ්‍රම පිරිවැය සමාන නොවන බැවින් සෑම රටක්ම තමන්ට 'සාපේක්ෂ වාසියක්' (Comparative Advantage) ඇති භාණ්ඩ නිපදවා අනෙක් භාණ්ඩ හුවමාරු කර ගැනීම", "සෑම රටක්ම සියල්ල තනිව නිපදවීම", "මුදල් ඉරා දැමීම", "වෙළඳාම තහනම් කිරීම",
        "ශ්‍රී ලංකාව තේ, කුළුබඩු හා ඇඟලුම් අපනයනය කර බොරතෙල්, ඖෂධ, යන්ත්‍රෝපකරණ හා තිරිඟු ආනයනය කිරීම මීට නිදසුනකි."),
      q(t, "'වෙළඳ ශේෂය' (Balance of Trade) අහිතකර හෙවත් 'වෙළඳ හිඟයක්' (Trade Deficit) ඇතිවන්නේ කුමන අවස්ථාවේදීද?",
        "රටක ආනයන වියදම (Imports) එහි අපනයන ආදායමට (Exports) වඩා වැඩි වන විට", "අපනයන ආදායම ආනයන වියදමට වඩා වැඩි වන විට", "ආනයන හා අපනයන ශුන්‍ය වන විට", "සංචාරකයන් වැඩි වන විට",
        "අගය එකතු කළ අපනයන වැඩි කිරීම හා අත්‍යවශ්‍ය නොවන ආනයන දේශීයව නිපදවීම වෙළඳ හිඟය අඩු කිරීමට උපකාරී වේ."),
      q(t, "'තීරුබදු' (Tariffs) සහ 'කෝටා' (Quotas) වැනි ආරක්ෂණවාදී වෙළඳ ප්‍රතිපත්ති රජයන් විසින් යොදා ගන්නේ ඇයි?",
        "විදේශීය ලාභ ආනයනවලින් දේශීය ගොවීන් හා නව දේශීය කර්මාන්ත ආරක්ෂා කර ගැනීමට හා රාජ්‍ය ආදායම වැඩි කිරීමට", "දේශීය කර්මාන්ත වැසීමට", "විදේශ භාණ්ඩ නොමිලේ දීමට", "අපනයන තහනම් කිරීමට",
        "ලෝක වෙළඳ සංවිධානය (WTO) රටවල් අතර අසාධාරණ වෙළඳ බාධක අඩු කර නීතිමය රාමුවක් තුළ නිදහස් වෙළඳාම ප්‍රවර්ධනය කරයි."),
      q(t, "'සංචාරක ව්‍යාපාරය' (Tourism) 'අදෘශ්‍යමාන අපනයනයක්' (Invisible Export) ලෙස හඳුන්වනු ලබන්නේ ඇයි?",
        "භෞතික භාණ්ඩ නැව්ගත කර රටින් පිටතට නොයවා, විදේශීය සංචාරකයන්ට රට තුළදී හෝටල්, ප්‍රවාහන හා මගපෙන්වීම් සේවා සපයා විදේශ විනිමය උපයන බැවින්", "සංචාරකයන් නොපෙනෙන බැවින්", "එය නීතිවිරෝධී බැවින්", "එයින් මුදල් නොලැබෙන බැවින්",
        "පාරිසරික සංචාරක ව්‍යාපාරය (Ecotourism) ස්වාභාවික පරිසරයට හානි නොකර දේශීය ප්‍රජාවට ප්‍රතිලාභ සලසන තිරසාර ආකෘතියකි."),
      q(t, "'අගය එකතු කිරීම' (Value Addition) ප්‍රාථමික භාණ්ඩ අපනයනය කරන රටවලට අතිශයින් වැදගත් වන්නේ ඇයි?",
        "අමු තේ කොළ, කුරුඳු කෝටු හෝ අමු රබර් කුට්ටි වෙනුවට සැකසූ සන්නාමගත තේ පැකට්, කුරුඳු තෙල් හා රබර් ටයර් අපනයනය කිරීමෙන් කිහිප ගුණයකින් වැඩි විදේශ විනිමයක් හා රැකියා ලැබෙන බැවින්", "භාණ්ඩයේ මිල අඩු කිරීමට", "කම්හල් වසා දැමීමට", "අමුද්‍රව්‍ය ඉවත දැමීමට",
        "සාමාන්‍යයෙන් අමු කෘෂි භාණ්ඩවල මිල ලෝක වෙළඳපොළේ ඉතා අඩු හා අස්ථාවර මට්ටමක පවතී."),
      q(t, "'සැපයුම් දාම කළමනාකරණයේ' 'Just-In-Time (JIT)' නිෂ්පාදන ක්‍රමය (ටොයෝටා වැනි මෝටර් රථ කම්හල්) මගින් ලැබෙන වාසිය හා අවදානම කුමක්ද?",
        "විශාල ගබඩා වියදම් අඩු වන නමුත් සුනාමි, වසංගත හෝ ඇළ මාර්ග අවහිර වීමකදී අමතර කොටස් ප්‍රමාද වුවහොත් මුළු නිෂ්පාදනයම ක්ෂණිකව නතර වේ", "ගබඩා කිලෝමීටර 100 ක් පුරවා තැබීම", "වාහන නිපදවීම නැවැත්වීම", "කිසිදු අවදානමක් නොමැති වීම",
        "COVID-19 වසංගතය හා සූවස් ඇළේ නැව් සිරවීම ගෝලීය JIT සැපයුම් දාමවල අවදානම් හෙළි කළේය."),
      q(t, "'කලාපීය ආර්ථික හවුල්කාරිත්ව / වෙළඳ සංවිධාන' (Trade Blocs - උදා: EU, ASEAN, USMCA) පිහිටුවීමේ ප්‍රධාන ආර්ථික අරමුණ කුමක්ද?",
        "සාමාජික රටවල් අතර ආනයන බදු අඩු කර හෝ ඉවත් කර භාණ්ඩ, සේවා හා ප්‍රාග්ධනය නිදහසේ ගලා යාමට ඉඩ සලසා කලාපීය ආර්ථික වර්ධනය වේගවත් කිරීම", "රටවල් අතර වෙළඳාම සම්පූර්ණයෙන් නැවැත්වීම", "එක් රටකට පමණක් ආහාර සීමා කිරීම", "මුහුදු ගමන් තහනම් කිරීම",
        "දකුණු ආසියාවේ කලාපීය සහයෝගීතාව සඳහා SAARC සහ SAFTA (South Asian Free Trade Area) ගිවිසුම් ඇති කර ඇත."),
      q(t, "'ගෝලීයකරණය' (Globalization) තුළ 'බහුජාතික සමාගම්' (MNCs / TNCs) ඉටු කරන ප්‍රධාන කාර්යභාරය කුමක්ද?",
        "මූලස්ථානය එක් රටක තබාගෙන ලොව පුරා රටවල් ගණනාවක පර්යේෂණ, අමුද්‍රව්‍ය ලබාගැනීම, නිෂ්පාදන කම්හල් හා අලෙවි ජාල මෙහෙයවමින් ලෝක ආර්ථිකය ඒකාබද්ධ කිරීම", "එක් ගමක පමණක් වෙළඳාම් කිරීම", "අන්තර්ජාලය තහනම් කිරීම", "අපනයන නැවැත්වීම",
        "MNC ආයෝජන රටවලට නව තාක්ෂණය හා රැකියා ගෙන එන නමුත් දේශීය කුඩා ව්‍යාපාරවලට දැඩි තරඟයක්ද එල්ල කරයි."),
      q(t, "'විදුලි වාණිජ්‍යය' (E-Commerce) සහ ඩිජිටල් සේවා ආර්ථික භූගෝල විද්‍යාවේ 'දුරස්ථභාවයේ බාධාව' (Friction of Distance) වෙනස් කර ඇත්තේ කෙසේද?",
        "ග්‍රාමීය කුඩා ව්‍යවසායකයින්ට හා මෘදුකාංග ඉංජිනේරුවන්ට පවා අන්තර්ජාලය හරහා ලෝකයේ ඕනෑම ගනුදෙනුකරුවෙකුට සේවා හා භාණ්ඩ සෘජුවම අලෙවි කිරීමට හැකි වීම", "සියලු කඩ සාප්පු වැසීම", "ප්‍රවාහනය අනවශ්‍ය වීම", "දුර වැඩි වීම",
        "කෙසේ වෙතත් භෞතික භාණ්ඩ බෙදා හැරීම සඳහා කාර්යක්ෂම තැපැල් හා කුරියර් ප්‍රවාහන ජාල තවමත් අත්‍යවශ්‍ය වේ."),
      q(t, "'තොරතුරු තාක්ෂණ හා ව්‍යාපාර ක්‍රියාවලි බාහිරින් ඉටු කිරීම' (IT-BPM Outsourcing) අංශයේදී ඉන්දියාව, පිලිපීනය හා ශ්‍රී ලංකාව සාර්ථක වීමට බලපෑ සාධක මොනවාද?",
        "ඉහළ ගණිත හා ඉංජිනේරු අධ්‍යාපන මට්ටම, ඉංග්‍රීසි භාෂා නිපුණතාව, සාපේක්ෂව තරඟකාරී වැටුප් සහ කාල කලාප වාසිය", "විශාල ගල් අඟුරු පතල් තිබීම", "තෙල් නිධි තිබීම", "ඉහළ මෝසම් වැසි තිබීම",
        "කොළඹ හා මහනුවර පරිගණක මෘදුකාංග හා ගිණුම්කරණ සේවා කර්මාන්තශාලාවල දුමාරයකින් තොරව ඉහළ විදේශ විනිමයක් උපයන අංශයකි."),
      q(t, "සාම්ප්‍රදායික කර්මාන්ත අතර ශ්‍රී ලංකාවේ 'මොරටුව' (ලී බඩු), 'අම්බලන්ගොඩ' (වෙස් මුහුණු), 'පිළිමතලාව/ගඩලාදෙණිය' (පිත්තල) හා 'රත්නපුර' (මැණික් කැපීම) එක් එක් ප්‍රදේශවල ඒකරාශී වී ඇත්තේ ඇයි?",
        "පාරම්පරික ශිල්පීය දැනුම පරම්පරාවෙන් පරම්පරාවට රැඳී පැවතීම (Inherited Skills), දේශීය අමුද්‍රව්‍ය සමීපතාව සහ ස්ථාපිත වෙළඳපොළ කීර්තිය නිසා", "නීතියෙන් වෙනත් තැනකට යාම තහනම් නිසා", "වරායවල් නිසා", "හිම පතනය නිසා",
        "මෙය ආර්ථික භූගෝල විද්‍යාවේ 'කාර්මික අවස්ථිතිභාවය / ඓතිහාසික ස්ථානගත වීම' (Industrial Inertia) ලෙසද හඳුන්වනු ලැබේ."),
      q(t, "'විදුලි වාහන (EV) හා අර්ධ සන්නායක (Semiconductor Chips)' නිෂ්පාදනය වර්තමාන ලෝක ආර්ථික භූගෝල විද්‍යාවේ උපායමාර්ගිකම කර්මාන්ත බවට පත්ව ඇත්තේ ඇයි?",
        "සියලුම නවීන ඉලෙක්ට්‍රොනික උපාංග, ස්මාර්ට්ෆෝන්, වෛද්‍ය උපකරණ, මෝටර් රථ හා හරිත බලශක්ති පද්ධති ක්‍රියාත්මක වීමට මයික්‍රොචිප් අත්‍යවශ්‍ය වන බැවින්", "ඒවා ආහාර බෝග වන බැවින්", "ඒවා ලී වලින් සාදන බැවින්", "ඒවා ජල විදුලිය නොමැතිව වැඩ නොකරන බැවින්",
        "තායිවානය (TSMC), දකුණු කොරියාව, ඇමරිකාව, ජපානය හා නෙදර්ලන්තය (ASML) ගෝලීය අර්ධ සන්නායක සැපයුම් දාමයේ ප්‍රධාන කේන්ද්‍ර වේ."),
      q(t, "'වනාන්තර ආශ්‍රිත කර්මාන්ත' වන කඩදාසි, පල්ප් හා ලී මෝල් බොහෝ විට උතුරු කැනඩාව, ස්වීඩනය හා ෆින්ලන්තය වැනි කේතුධර (Taiga) වනාන්තර කලාපවල පිහිටුවා ඇත්තේ ඇයි?",
